#include <iostream>
#include <utility>
using namespace std;

class Buffer {
    int* data;
public:
    Buffer(size_t size) : data(new int[size]) {}
    ~Buffer() { delete[] data; }
    // Move Constructor
    Buffer(Buffer&& other) noexcept : data(other.data) {
        other.data = nullptr;
    }
};

int main() {
    Buffer b1(100);
    Buffer b2 = std::move(b1); // Transfer ownership
    return 0;
}

